local config = {
  ui_story_31870401_1_dialog_content = "Ah, PlayerName, akhirnya kamu di sini.",
  ui_story_31870401_2_dialog_content = "Squawk sangat khawatir sejak Jabber menghilang.",
  ui_story_31870401_3_dialog_content = "Mengomel! Lebih banyak makanan untukku!",
  ui_story_31870401_4_dialog_content = "Jadi, namanya jalak ini Squawk?",
  ui_story_31870401_5_dialog_content = "Tampaknya tidak terlalu khawatir...",
  ui_story_31870401_6_dialog_content = "Oh, Squawk hanya mengoceh omong kosong lagi. Jangan dengarkan dia.",
  ui_story_31870401_7_dialog_content = "Tidak, kamu yang mengeluarkan omong kosong! Mengomel!",
  ui_story_31870401_8_dialog_content = "Diam, kamu! Pokoknya, Jabber itu jalakku yang lain, yang mirip dengan Squawk.",
  ui_story_31870401_9_dialog_content = "Jadi, pernahkah kamu melihatnya di sekitar sini?",
  ui_story_31870401_10_dialog_content = "Aku, eh... sepertinya tidak bisa mengingat.",
  ui_story_31870401_11_dialog_content = "Mungkin kita bisa mulai dengan mengingat di mana kamu kehilangan barang itu?",
  ui_story_31870401_12_dialog_content = "Kemana saja kamu dan apa yang kamu lakukan dalam dua hari terakhir ini?",
  ui_story_31870401_13_dialog_content = "Nah, sekarang setelah kamu menyebutkannya, aku memang mengunjungi banyak tempat dalam rentang waktu itu.",
  ui_story_31870401_14_dialog_content = "Saya sedang dalam perjalanan melintasi seluruh Astra, mengumpulkan berbagai gosip dan cerita aneh...",
  ui_story_31870401_15_dialog_content = "Dan menggunakannya untuk menyelesaikan bab ketiga dari <color=#FFB400>\"Gulungan Kenaikan Ilahi.\"</color>",
  ui_story_31870401_16_dialog_content = "\"Scroll of Divine Ascension\"? Terdengar cukup rumit.",
  ui_story_31870401_17_dialog_content = "Wajar saja, mengingat karya misterius ini diberikan kepada saya oleh seseorang yang bahkan lebih misterius.",
  ui_story_31870401_18_dialog_content = "Bab pertama terdiri dari <color=#FFB400>berbagai macam legenda aneh dan kuno</color> dari seluruh dunia.",
  ui_story_31870401_19_dialog_content = "Bab kedua penuh dengan <color=#FFB400>tulisan dan simbol misterius</color>, semuanya sama sekali tidak dapat dipahami...",
  ui_story_31870401_20_dialog_content = "Kedengarannya mengagumkan! Bagaimana dengan bab ketiga?",
  ui_story_31870401_21_dialog_content = "Bab ketiga... adalah kumpulan <color=#FFB400>cerita aneh dan rumor</color> yang dikumpulkan oleh saya sendiri!",
  ui_story_31870401_22_dialog_content = "Dan saya berhak atas penjelasan akhir dari kontennya.",
  ui_story_31870401_23_dialog_content = "(Entah mengapa, aku merasa ini tidak memberikan keadilan pada gulungan ini...)",
  ui_story_31870401_24_dialog_content = "Tetapi, aku ingin kamu membacanya sendiri. Melihat itu lebih meyakinkan, setelah semua.",
  ui_story_31870401_25_dialog_content = "Hanya ada satu baris teks di setiap halaman untuk chapter ketiga, jadi jangan ragu untuk melihatnya.",
  ui_story_31870401_26_dialog_content = "Oke, mari kita lihat...",
  ui_story_31870401_27_dialog_content = "<size=50>\"Persiapan rahasia untuk menggantikan Grand Marshal sedang berlangsung\"?!</size>",
  ui_story_31870401_28_dialog_content = "Bagian ini berarti bahwa seorang Komandan Illumina berambut merah muda tertentu telah diam-diam meniru tulisan tangan Grand Marshal, di antara hal-hal lainnya.",
  ui_story_31870401_29_dialog_content = "Dan... <size=50>\"Urusan rahasia istana kerajaan Northland terbongkar\"?!</size>",
  ui_story_31870401_30_dialog_content = "Ah, ya, bagian ini. Ini hanya berarti bahwa ratu Northland cenderung bicara dalam tidur, di antara hal-hal lainnya.",
  ui_story_31870401_31_dialog_content = "... Aku belum pernah dengar tentang semua ini! Dan kenapa kamu membuatnya terdengar lebih sensasional dari yang sebenarnya?!",
  ui_story_31870401_32_dialog_content = "Pokoknya, kamu pasti sudah cukup familiar dengan Astra sekarang setelah berkunjung ke begitu banyak tempat, kan?",
  ui_story_31870401_33_dialog_content = "Perjalanan saya hanyalah bagian dari pekerjaan saya. Kepandaian saya tentang negeri ini pasti tak sebanding dengan milik Anda, saya yakin.",
  ui_story_31870401_34_dialog_content = "Dalam dua hari terakhir, saya mengunjungi kembali <color=#FFB400>Teluk Twin Pavilions</color>, <color=#FFB400>Gurun Rediesel</color>, dan <color=#FFB400>Umbraton</color> untuk mendengar gosip terbaru.",
  ui_story_31870401_35_dialog_content = "Apakah kamu akrab dengan salah satu tempat ini?",
  ui_story_31870401_36_dialog_content = "Saya yakin seseorang seperti kamu pasti memiliki teknik khusus <color=#FFB400>istimewa</color> untuk menemukan burung, bukan?",
  ui_story_31870401_37_dialog_content = "Mana kutahu? Aku tidak bersamamu saat kamu...",
  ui_story_31870401_38_dialog_content = "Tunggu, aku mengerti!",
  ui_story_31870401_39_option_content = "Gunakan kemampuan psikis",
  ui_story_31870401_40_dialog_content = "Saya dapat menggunakan kekuatan saya untuk melihat ingatan Anda berdasarkan isi dari ketiga halaman ini.",
  ui_story_31870401_41_dialog_content = "Mungkin aku akan bisa menemukan beberapa petunjuk yang akan membawa kita ke Jabber!",
  ui_story_31870401_42_option_content = "Hubungi pihak-pihak yang terlibat dalam gosip tersebut",
  ui_story_31870401_43_dialog_content = "Itu tidak bisa, sayangnya. Sebagai seorang pengembara pengumpul rumor di dunia, saya selalu mencuci tangan dari masalah lama ketika urusan saya selesai.",
  ui_story_31870401_44_dialog_content = "Saya sudah cukup bersyukur bahwa pihak-pihak yang terlibat tidak mencoba untuk mengejar saya. Bagaimana mungkin saya bisa menghubungi mereka?",
  ui_story_31870401_45_dialog_content = "Aku mengerti... Sepertinya aku harus menggunakan kekuatan psikisku, ya?",
  ui_story_31870401_46_dialog_content = "Aku tahu kamu adalah orang yang tepat untuk dihubungi.",
  ui_story_31870401_47_dialog_content = "Nah, bisakah kamu mulai dengan kenangan saya tentang Twin Pavilions Bay?",
  ui_story_31870401_48_dialog_content = "Baik, bagian tentang Twin Pavilions Bay seharusnya... <color=#FFB400>\"Kecurigaan terhadap kapten Shadowind?!\"</color>",
  ui_story_31870401_49_option_content = "Force Boost!",
  ui_story_31870401_50_dialog_content = "Hei, apakah itu aku atau Kapten Yuebai yang akhir-akhir ini bertingkah aneh?",
  ui_story_31870401_51_dialog_content = "Aku tahu maksudmu. Dia pergi sendirian beberapa hari terakhir ini, dan kemudian memeriksa pakaiannya setiap kali kembali ke kapal udara.",
  ui_story_31870401_52_dialog_content = "Dia mungkin memastikan tidak ada yang menempel di pakaiannya. Aku sudah tahu sejak lama bahwa Umbraton penuh dengan orang baik dan buruk...",
  ui_story_31870401_53_dialog_content = "Hei, menurut kamu, apakah mungkin dia dibayar untuk menjadi informan bagi bos geng itu?",
  ui_story_31870401_54_dialog_content = "Sst! Sst!",
  ui_story_31870401_55_dialog_content = "…",
  ui_story_31870401_56_dialog_content = "C-Capten Yuebai!!",
  ui_story_31870401_57_dialog_content = "Oh? Apakah saya mencium gosip yang menarik?",
  ui_story_31870401_58_dialog_content = "Yuebai pergi!",
  ui_story_31870401_59_dialog_content = "Ikuti dia! Ikuti dia!",
  ui_story_31870401_60_dialog_content = "Aku tahu, aku tahu! Sekarang jangan berisik!",
  ui_story_31870401_61_dialog_content = "<color=#e8d9bb>Teluk Twin Pavilions</color>",
  ui_story_31870401_62_dialog_content = "…",
  ui_story_31870401_63_dialog_content = "Sepertinya dia takut diperhatikan. Apa yang sebenarnya dia lakukan?",
  ui_story_31870401_64_dialog_content = "Dia masuk ke sebuah toko!",
  ui_story_31870401_65_dialog_content = "Ini sebuah kedai!",
  ui_story_31870401_66_dialog_content = "Apakah ini salah satu kedai yang digunakan untuk pertemuan rahasia...?",
  ui_story_31870401_67_dialog_content = "Argh?!",
  ui_story_31870401_68_dialog_content = "Iyuh, bau busuk yang mengerikan!",
  ui_story_31870401_69_dialog_content = "Ayo semua! Coba <color=#FFB400>mie siput</color> lezat kami, produk baru langsung dari timur!",
  ui_story_31870401_70_dialog_content = "Meskipun baunya, camilan lezat ini akan membuat satu gigitan membawa Anda kembali ke Longzhou!",
  ui_story_31870401_71_dialog_content = "Yang biasa saja, tolong.",
  ui_story_31870401_72_dialog_content = "Mengerti! Satu mangkuk mie siput ekstra pedas dengan dua kali lipat siput dan tanpa rebung acar, segera disajikan! Silakan duduk, teman!",
  ui_story_31870401_73_dialog_content = "Ahhh, tidak bisa melupakan aroma masakan negeri kita.",
  ui_story_31870401_74_dialog_content = "(Jadi rahasia Yuebai adalah dia suka menyelinap keluar untuk makan mie siput...)",
  ui_story_31870401_75_dialog_content = "(Tunggu, apa yang sedang kulakukan? Seharusnya aku mencari Jabber!)",
  ui_story_31870401_76_dialog_content = "Namun, Mengoceh tetap bersama kamu dalam kenangan ini dari awal hingga akhir.",
  ui_story_31870401_77_dialog_content = "Saya rasa aman untuk mengatakan bahwa kamu tidak kehilangan itu di Twin Pavilions Bay.",
  ui_story_31870401_78_dialog_content = "Oh, begitu. Saya tidak tahu kalau kemampuan psikis kamu memungkinkan kamu melihat sesuatu dengan begitu jelas.",
  ui_story_31870401_79_dialog_content = "Sekarang, tolong buka halaman berikutnya dan bantu aku mencari lagi.",
  ui_story_31870401_80_dialog_content = "Tidak masalah. Halaman berikutnya adalah tentang... <color=#FFB400>\"Masa lalu dan kehidupan sekarang dari Lepidoz\"?!</color>",
  ui_story_31870401_81_option_content = "Force Boost!",
  ui_story_31870401_82_dialog_content = "<color=#e8d9bb>Gurun Rediesel</color>",
  ui_story_31870401_83_dialog_content = "Kamu tidak pernah istirahat?!",
  ui_story_31870401_84_dialog_content = "Kita juga butuh makan dan istirahat!",
  ui_story_31870401_85_dialog_content = "Tunjukkan sopan santun, kalian berdua! Aku sudah memberi kalian banyak buah selama perjalanan ini!",
  ui_story_31870401_86_dialog_content = "Sekarang kita punya gosip menarik tentang Yuebai, kita perlu memaksimalkan nilai gosip ini secepat mungkin.",
  ui_story_31870401_87_dialog_content = "Aku selalu terpesona oleh para Colossus di negeri ini.",
  ui_story_31870401_88_dialog_content = "Soroz—",
  ui_story_31870401_89_dialog_content = "Lepidoz—",
  ui_story_31870401_90_dialog_content = "Dan kapal dagang itu akan menjadi—",
  ui_story_31870401_91_dialog_content = "Bayangan!",
  ui_story_31870401_92_dialog_content = "Kapal dagang? Kapal dagang apa?",
  ui_story_31870401_93_dialog_content = "Ah ya, dan terkadang jawaban yang kita cari datang tepat menghampiri kita!",
  ui_story_31870401_94_dialog_content = "Hah? Saya tidak tahu apa yang sedang kamu bicarakan, tetapi apakah kamu di sini untuk bergabung dengan Rediesel Wrench?",
  ui_story_31870401_95_dialog_content = "Tidak, saya hanya memiliki rasa hormat dan kekaguman yang sangat besar kepada pemimpin Rediesel Wrench, itulah sebabnya saya datang ke sini untuk melaporkan beberapa informasi baru.",
  ui_story_31870401_96_dialog_content = "Cara bicaramu lucu, tahu nggak sih? Lagipula, apa yang istimewa tentang Sinsa?",
  ui_story_31870401_97_dialog_content = "(Uh-oh, sepertinya aku memuji orang yang salah...)",
  ui_story_31870401_98_dialog_content = "(Aku hanya perlu menyesuaikan pendekatan berdasarkan apa yang dia katakan!)",
  ui_story_31870401_99_dialog_content = "Tahu, melihat betapa besar dan kuatnya dirimu, aku yakin pemimpinmu pasti mempercayaimu dengan banyak rahasianya, ya?",
  ui_story_31870401_100_dialog_content = "Mata lo bagus, bro! Kebetulan nih, gue ini orang terkuat di seluruh Rediesel Wrench!",
  ui_story_31870401_101_dialog_content = "Tapi, uh... Rahasia jenis apa yang kamu bicarakan?",
  ui_story_31870401_102_dialog_content = "Saat ini saya memiliki gosip menarik terkait kapten kapal dagang Keluarga Lin. Apakah Anda tertarik untuk menukar rincian tentang keberadaan Lepidoz dengan itu?",
  ui_story_31870401_103_dialog_content = "Lepidoz, huh? Sinsa baru saja menemukannya dan kemudian memodifikasinya habis-habisan.",
  ui_story_31870401_104_dialog_content = "Sebenarnya bukan rahasia, mengingat orang-orang di sini suka mendaur ulang barang bekas seperti itu.",
  ui_story_31870401_105_dialog_content = "Mengenai di mana kami menemukan Lepidoz, saya tidak keberatan memberi tahu Anda juga: hampir semua yang kami temukan berasal langsung dari <color=#FFB400>sampah</color>! Hidup Rediesel Wrench!",
  ui_story_31870401_106_dialog_content = "Sampah?",
  ui_story_31870401_107_dialog_content = "Benar sekali! Entah itu Colossus besar di pinggir jalan atau mobil yang rusak... Semuanya bisa ditemukan di sini!",
  ui_story_31870401_108_dialog_content = "Lagipula, kebebasan adalah tujuan kita semua!",
  ui_story_31870401_109_dialog_content = "Itu mengingatkan saya... Kapal dagang apa yang Anda bicarakan? Apakah itu salah satu kapal yang berlabuh di pelabuhan daratan?",
  ui_story_31870401_110_dialog_content = "Ini tidak baik!",
  ui_story_31870401_111_dialog_content = "Lari, lari!",
  ui_story_31870401_112_dialog_content = "Hahaha! Maaf, aku harus pergi sekarang! Sampai jumpa lagi, kawan!",
  ui_story_31870401_113_dialog_content = "Saat itu, hal itu juga cukup mengejutkan bagiku.",
  ui_story_31870401_114_dialog_content = "(Jadi Sinsa lah yang memodifikasi Lepidoz...)",
  ui_story_31870401_115_dialog_content = "(Argh, fokus! Saya seharusnya mencari Jabber!)",
  ui_story_31870401_116_dialog_content = "Mengoceh juga ada di ingatan ini sepanjang waktu.",
  ui_story_31870401_117_dialog_content = "Teriakannya terdengar sama canggungnya dengan milikmu.",
  ui_story_31870401_118_dialog_content = "Aku terkejut kemampuan psikis kamu memungkinkan kamu untuk merasakan perasaan targetmu juga...",
  ui_story_31870401_119_dialog_content = "Aku tahu apa yang akan kamu katakan. Balik ke halaman berikutnya, 'kan?",
  ui_story_31870401_120_dialog_content = "Ya, silakan! Kamu kan peramal handal, tahu?",
  ui_story_31870401_121_dialog_content = "Baik, sekarang untuk halaman terakhir—<color=#FFB400>\"Pesta ulang tahun besar Tuan Putri Zhuohua terungkap\"?!</color>",
  ui_story_31870401_122_option_content = "Force Boost!",
  ui_story_31870401_123_dialog_content = "Tampaknya rumor seputar Yuebai kini sudah lebih atau kurang mereda.",
  ui_story_31870401_124_dialog_content = "Meskipun sudah mengeluarkan darah, keringat, dan air mata untuk tugas ini, aku tetap merasa sedikit bosan.",
  ui_story_31870401_125_dialog_content = "Bualkan saja, kenapa tidak?!",
  ui_story_31870401_126_dialog_content = "Wah, sangat rendah hati!",
  ui_story_31870401_127_dialog_content = "Ugh, semua ocehanmu yang tak henti-hentinya benar-benar membuat sulit untuk tenang.",
  ui_story_31870401_128_dialog_content = "... Hmm? Tunggu, sepertinya aku mendengar sesuatu selain suara menyebalkan kalian—",
  ui_story_31870401_129_dialog_content = "Kudengar alasan kapten tidak mau berbisnis dengan Umbraton adalah karena tempat itu seperti neraka yang digambarkan dalam mitos.",
  ui_story_31870401_130_dialog_content = "Tidak hanya itu, mereka mengatakan bahwa Shadowlord terlihat seperti memiliki tanduk banteng dan wajah kuda, serta selalu ditemani anjing hitam dan anjing putih di sisinya...",
  ui_story_31870401_131_dialog_content = "... Dan dari mana kamu mendengar hal-hal itu?",
  ui_story_31870401_132_dialog_content = "Lebih banyak cerita hantu, ya? Sepertinya orang-orang ini hanya berspekulasi tentang Umbraton, seperti sebelumnya.",
  ui_story_31870401_133_dialog_content = "Kalau aku tidak pergi ke neraka, siapa lagi yang akan pergi?",
  ui_story_31870401_134_dialog_content = "<color=#e8d9bb>Umbraton</color>",
  ui_story_31870401_135_dialog_content = "Jalan yang biasa!",
  ui_story_31870401_136_dialog_content = "Toko biasa!",
  ui_story_31870401_137_dialog_content = "Tampaknya cerita tentang \"neraka\" ini sangat dilebih-lebihkan.",
  ui_story_31870401_138_dialog_content = "... Oh? Apakah itu wajah yang familier yang aku lihat?",
  ui_story_31870401_139_dialog_content = "Yang Mulia, kios ini tampaknya menjual barang-barang yang digunakan untuk metode peramalan Astra.",
  ui_story_31870401_140_dialog_content = "Kartu-kartu ini... Saya percaya mereka disebut kartu tarot? Menarik.",
  ui_story_31870401_141_dialog_content = "Jiu, saya ingin mencobanya, untuk membaca keberuntungan saya dengan mereka.",
  ui_story_31870401_142_dialog_content = "Tapi Yang Mulia...",
  ui_story_31870401_143_dialog_content = "Mari kita pilih yang di samping tangan saya untuk kartu pertama.",
  ui_story_31870401_144_dialog_content = "Bisakah kamu jelaskan arti dari kartu ini?",
  ui_story_31870401_145_dialog_content = "Oh... Itu Menara dalam posisi tegak. Bukan pertanda baik, temanku.",
  ui_story_31870401_146_dialog_content = "Yang Mulia, saya yakin ini hanyalah mainan untuk mengisi waktu, jadi tolong jangan...",
  ui_story_31870401_147_dialog_content = "Tolong jangan percaya sama sekali pada hal itu.",
  ui_story_31870401_148_dialog_content = "Saya melihat jalan-jalan di Umbraton juga tidak aman dari penipu.",
  ui_story_31870401_149_dialog_content = "Tapi kami berdua adalah peramal, Putri Zhuohua. Mengapa meragukan kemampuan saya dan tidak pria ini?",
  ui_story_31870401_150_dialog_content = "Saya tidak pernah percaya pada peramal atau ramalan mereka yang tak berdasar. Saya sudah mengatakannya pada Anda di kapal, atau Anda lupa?",
  ui_story_31870401_151_dialog_content = "Jeruk keprok yang tumbuh di selatan adalah jeruk keprok!",
  ui_story_31870401_152_dialog_content = "Tapi mereka akan menjadi jeruk pahit di utara!",
  ui_story_31870401_153_dialog_content = "Putri Zhuohua, akan menjadi kehormatan bagi saya untuk membaca keberuntungan Anda, jika Anda bersedia? Saya yakin metode ramalan dari tanah air kita akan menghasilkan prediksi yang sangat berbeda.",
  ui_story_31870401_154_dialog_content = "Yang aku butuhkan hanyalah tanggal ulang tahunmu, dan tidak lebih.",
  ui_story_31870401_155_dialog_content = "…",
  ui_story_31870401_156_dialog_content = "Baiklah, aku penasaran untuk melihat ramalan setengah matang apa yang akan kamu berikan padaku.",
  ui_story_31870401_157_dialog_content = "Hari keempat bulan keempat... Angka yang cukup spesial untuk tanggal lahir Anda, harus saya katakan.",
  ui_story_31870401_158_dialog_content = "Lihatlah tongkat-tongkat ini, genggam takdir. Dengan Yin dan Yang bersatu, segala sesuatu diberi bentuk...",
  ui_story_31870401_159_dialog_content = "Oh ya. Ini pertama kalinya aku melihat takdir yang sangat aneh seperti ini.",
  ui_story_31870401_160_dialog_content = "Tak usah berlebihan, langsung saja ceritakan keberuntungan saya.",
  ui_story_31870401_161_dialog_content = "Ular Yang dan Harimau Yin adalah keberuntungan yang juga dikenal sebagai \"kepala ular dan ekor harimau\", di mana ular melambangkan cahaya dan harimau melambangkan kegelapan.",
  ui_story_31870401_162_dialog_content = "Meskipun terdengar aneh, ramalan ini sebenarnya memiliki makna yang mendalam.",
  ui_story_31870401_163_dialog_content = "Dari apa yang bisa saya lihat, takdir Anda adalah penuh dengan banyak perjuangan, tetapi di akhir perjalanan Anda terdapat persimpangan jalan, dan di balik itu terdapat <color=#FFB400>keberuntungan</color>.",
  ui_story_31870401_164_dialog_content = "Eh?",
  ui_story_31870401_165_dialog_content = "Tapi ketika saya masih anak-anak, peramal mengatakan bahwa saya ditakdirkan untuk mengalami nasib buruk...",
  ui_story_31870401_166_dialog_content = "Takdir dan keberuntungan adalah dua hal yang sangat berbeda. Takdir ditentukan oleh langit, sedangkan keberuntungan bisa diubah oleh tangan kita sendiri.",
  ui_story_31870401_167_dialog_content = "Jika kamu memutuskan untuk tetap pada jalur saat ini, hidup akan berubah menjadi lebih baik. Segalanya tidak akan seburuk dulu, aku yakin.",
  ui_story_31870401_168_dialog_content = "Untuk kapan itu terjadi, saya tidak bisa mengatakan. Setelah semua, beberapa hal harus tetap rahasia.",
  ui_story_31870401_169_dialog_content = "Namun, ini hanyalah prediksi pribadiku. Kamu bebas untuk percaya pada prediksi mana pun yang diberikan kepadamu, atau bahkan tidak sama sekali.",
  ui_story_31870401_170_dialog_content = "Sekarang, saya harus pergi. Sampai jumpa lagi, Yang Mulia.",
  ui_story_31870401_171_dialog_content = "Selamat tinggal!",
  ui_story_31870401_172_dialog_content = "Sampai jumpa lagi!",
  ui_story_31870401_173_dialog_content = "…",
  ui_story_31870401_174_dialog_content = "Yang Mulia... Apa yang sedang Anda pikirkan?",
  ui_story_31870401_175_dialog_content = "... Bukan apa-apa. Ayo Jiu, kita harus kembali ke kapal sekarang.",
  ui_story_31870401_176_dialog_content = "Ah, tampaknya takdir Tuan Putri Zhuohua jauh dari biasa. Langit telah menaruh tanggung jawab besar di pundaknya.",
  ui_story_31870401_177_dialog_content = "(Jadi itulah jenis keberuntungan yang diberikan pada Dantang saat ia lahir...)",
  ui_story_31870401_178_dialog_content = "(Oh, tidak lagi! Harus menemukan Jabber!)",
  ui_story_31870401_179_dialog_content = "Tidak ada petunjuk di halaman ini juga, jadi sepertinya aku harus mencoba yang berikutnya...",
  ui_story_31870401_180_dialog_content = "Berhenti! Jangan balik halaman itu!",
  ui_story_31870401_181_dialog_content = "Eh?",
  ui_story_31870401_182_dialog_content = "Saya sangat menyarankan agar kamu tidak membaca lebih jauh, PlayerName. Seperti yang pernah saya katakan sebelumnya, ada beberapa hal yang harus tetap dirahasiakan.",
  ui_story_31870401_183_dialog_content = "Baiklah, jadi misterius saja...",
  ui_story_31870401_184_dialog_content = "Mohon maafkan saya, terutama karena seharusnya saya berterima kasih padamu karena telah menggunakan kekuatan psikismu untuk membantu saya.",
  ui_story_31870401_185_dialog_content = "Kurasa aku tahu di mana menemukan Jabber sekarang.",
  ui_story_31870401_186_dialog_content = "Apa?! Kamu lakukan?!",
  ui_story_31870401_187_dialog_content = "Tapi, aku tidak berhasil menemukan apa pun...",
  ui_story_31870401_188_dialog_content = "Sebanyak yang ingin aku mengantarmu, aku harus mencari Jabber segera. Aku akan pastikan berterima kasih padamu dengan benar di lain waktu.",
  ui_story_31870401_189_dialog_content = "Jangan khawatir. Bukan seperti aku benar-benar melakukan sesuatu...",
  ui_story_31870401_190_dialog_content = "Sampai jumpa dulu! Sampai jumpa di lain waktu!",
  ui_story_31870401_191_dialog_content = "A-Aku akan pergi kalau begitu!",
  ui_story_31870401_192_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian</color>",
  ui_story_31870401_193_dialog_content = "…",
  ui_story_31870401_194_dialog_content = "Baiklah, kalian berdua bisa keluar sekarang.",
  ui_story_31870401_195_dialog_content = "Selembar papan saja tidak membuat perahu!",
  ui_story_31870401_196_dialog_content = "Seorang aktor saja tidak membuat sandiwara!",
  ui_story_31870401_197_dialog_content = "Kita berhasil melakukan pekerjaan yang hebat bersama!",
  ui_story_31870401_198_dialog_content = "Dan kita bisa makan buah sepanjang hari!",
  ui_story_31870401_199_dialog_content = "Ya, ya, dan aku juga bersedia untuk mengabaikan kesalahan Squawk, meskipun itu hampir merusak segalanya.",
  ui_story_31870401_200_dialog_content = "Ini dia buah persediaan spesial yang dijanjikan. Sekarang, berhenti mengganggu pekerjaan saya!",
  ui_story_31870401_201_dialog_content = "Saatnya makan! Saatnya makan!",
  ui_story_31870401_202_dialog_content = "(Fiuh, mengundang PlayerName ternyata juga sangat menguntungkan!)",
  ui_story_31870401_203_dialog_content = "(Tampaknya saya memiliki entri lain untuk ditambahkan ke \"Gulungan Kenaikan Ilahi\" sekarang.)",
  ui_story_31870401_204_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_31870401_205_dialog_content = "\"Mengalami dan mengamati kemampuan psikis dari Caelestite.\""
}
return config
